#include <zephyr/ztest.h>
#include <zephyr/pinctrl.h>
#include <zephyr/devicetree.h>

#include "pinctrl_soc.h"

/*
 * The pinctrl configurations are defined in the board devicetree file.
 * The test uses the nodes with compatible "test-pinctrl-device".
 */
#define PINCTRL_NODE_0 DT_NODELABEL(test_device0)
#define PINCTRL_NODE_1 DT_NODELABEL(test_device1)

/* pinctrl configurations for test_device0 */
#define PINS_DEFAULT_0 Z_PINCTRL_STATE_PINS_INIT(PINCTRL_NODE_0, default)
#define PINS_SLEEP_0 Z_PINCTRL_STATE_PINS_INIT(PINCTRL_NODE_0, sleep)

static const pinctrl_soc_pin_t pcfg0_pins_default[] = PINS_DEFAULT_0;
static const pinctrl_soc_pin_t pcfg0_pins_sleep[] = PINS_SLEEP_0;

static const struct pinctrl_state pcfg0_states[] = {
	PINCTRL_STATE_INIT(pcfg0_pins_default, "default"),
	PINCTRL_STATE_INIT(pcfg0_pins_sleep, "sleep"),
};

static const struct pinctrl_dev_config pcfg0 = {
	.dev = DEVICE_DT_GET(PINCTRL_NODE_0),
	.states = pcfg0_states,
	.state_cnt = ARRAY_SIZE(pcfg0_states),
};

/* pinctrl configurations for test_device1 */
#define PINS_DEFAULT_1 Z_PINCTRL_STATE_PINS_INIT(PINCTRL_NODE_1, default)
#define PINS_SLEEP_1 Z_PINCTRL_STATE_PINS_INIT(PINCTRL_NODE_1, sleep)

static const pinctrl_soc_pin_t pcfg1_pins_default[] = PINS_DEFAULT_1;
static const pinctrl_soc_pin_t pcfg1_pins_sleep[] = PINS_SLEEP_1;

static const struct pinctrl_state pcfg1_states[] = {
	PINCTRL_STATE_INIT(pcfg1_pins_default, "default"),
	PINCTRL_STATE_INIT(pcfg1_pins_sleep, "sleep"),
};

static const struct pinctrl_dev_config pcfg1 = {
	.dev = DEVICE_DT_GET(PINCTRL_NODE_1),
	.states = pcfg1_states,
	.state_cnt = ARRAY_SIZE(pcfg1_states),
};

static void pinctrl_api_before(void *data)
{
	ARG_UNUSED(data);

	/*
	 * The following check is not part of the test, but it is used to
	 * verify that the pinctrl configurations are correctly obtained from
	 * devicetree.
	 */
	zassert_equal(pcfg0.state_cnt, 2, "invalid state count");
	zassert_equal(pcfg1.state_cnt, 2, "invalid state count");
}

ZTEST(pinctrl_api, test_config_dev0)
{
	int ret;

	/* test normal configuration */
	ret = pinctrl_apply_state(&pcfg0, PINCTRL_STATE_DEFAULT);
	zassert_equal(ret, 0, "failed to apply default state");
	zassert_equal(pinctrl_soc_check_config(&pcfg0, PINCTRL_STATE_DEFAULT),
		      true, "invalid default config");

	ret = pinctrl_apply_state(&pcfg0, PINCTRL_STATE_SLEEP);
	zassert_equal(ret, 0, "failed to apply sleep state");
	zassert_equal(pinctrl_soc_check_config(&pcfg0, PINCTRL_STATE_SLEEP),
		      true, "invalid sleep config");

	/* test invalid configuration */
	ret = pinctrl_apply_state(&pcfg0, 2);
	zassert_not_equal(ret, 0, "succeeded to apply invalid state");
}

ZTEST(pinctrl_api, test_config_dev1)
{
	int ret;

	/* test normal configuration */
	ret = pinctrl_apply_state(&pcfg1, PINCTRL_STATE_DEFAULT);
	zassert_equal(ret, 0, "failed to apply default state");
	zassert_equal(pinctrl_soc_check_config(&pcfg1, PINCTRL_STATE_DEFAULT),
		      true, "invalid default config");

	ret = pinctrl_apply_state(&pcfg1, PINCTRL_STATE_SLEEP);
	zassert_equal(ret, 0, "failed to apply sleep state");
	zassert_equal(pinctrl_soc_check_config(&pcfg1, PINCTRL_STATE_SLEEP),
		      true, "invalid sleep config");

	/* test invalid configuration */
	ret = pinctrl_apply_state(&pcfg1, 2);
	zassert_not_equal(ret, 0, "succeeded to apply invalid state");
}

ZTEST(pinctrl_api, test_lookup_state)
{
	int ret;
	pinctrl_state_t state;

	ret = pinctrl_lookup_state(&pcfg0, "default", &state);
	zassert_equal(ret, 0, "failed to lookup default state");
	zassert_equal(state, PINCTRL_STATE_DEFAULT, "invalid default state");

	ret = pinctrl_lookup_state(&pcfg0, "sleep", &state);
	zassert_equal(ret, 0, "failed to lookup sleep state");
	zassert_equal(state, PINCTRL_STATE_SLEEP, "invalid sleep state");

	ret = pinctrl_lookup_state(&pcfg0, "invalid", &state);
	zassert_not_equal(ret, 0, "succeeded to lookup invalid state");
}

ZTEST(pinctrl_api, test_apply_state)
{
	const struct device *dev = DEVICE_DT_GET(PINCTRL_NODE_0);
	int ret;

	ret = pinctrl_apply_state_by_name(dev, "default");
	zassert_equal(ret, 0, "failed to apply default state");
	zassert_equal(pinctrl_soc_check_config(&pcfg0, PINCTRL_STATE_DEFAULT),
		      true, "invalid default config");

	ret = pinctrl_apply_state_by_name(dev, "sleep");
	zassert_equal(ret, 0, "failed to apply sleep state");
	zassert_equal(pinctrl_soc_check_config(&pcfg0, PINCTRL_STATE_SLEEP),
		      true, "invalid sleep config");

	ret = pinctrl_apply_state_by_name(dev, "invalid");
	zassert_not_equal(ret, 0, "succeeded to apply invalid state");
}

/* test data for test_update_states */
static const pinctrl_soc_pin_t test_device0_alt_default_pins[] = {
	PINCTRL_SOC_PIN_INIT(PINCTRL_PIN_DEV_0, 10, 1),
};
static const pinctrl_soc_pin_t test_device0_alt_sleep_pins[] = {
	PINCTRL_SOC_PIN_INIT(PINCTRL_PIN_DEV_0, 11, 0),
};
static const struct pinctrl_state test_device0_alt_states[] = {
	PINCTRL_STATE_INIT(test_device0_alt_default_pins, "default"),
	PINCTRL_STATE_INIT(test_device0_alt_sleep_pins, "sleep"),
};
static const struct pinctrl_state test_device0_alt_invalid_states[] = {
	PINCTRL_STATE_INIT(test_device0_alt_default_pins, "invalid"),
	PINCTRL_STATE_INIT(test_device0_alt_sleep_pins, "sleep"),
};

ZTEST(pinctrl_api, test_update_states)
{
	const struct device *dev = DEVICE_DT_GET(PINCTRL_NODE_0);
	int ret;

	/* test valid update */
	ret = pinctrl_update_states(dev, test_device0_alt_states,
				    ARRAY_SIZE(test_device0_alt_states));
	zassert_equal(ret, 0, "failed to update states");

	ret = pinctrl_apply_state_by_name(dev, "default");
	zassert_equal(ret, 0, "failed to apply default state");
	zassert_equal(pinctrl_soc_check_pins(test_device0_alt_default_pins,
					     ARRAY_SIZE(test_device0_alt_default_pins)),
		      true, "invalid default config");

	/* test invalid update */
	ret = pinctrl_update_states(dev, test_device0_alt_invalid_states,
				    ARRAY_SIZE(test_device0_alt_invalid_states));
	zassert_not_equal(ret, 0, "succeeded to update with invalid states");

	/* test if previous configuration is still available */
	ret = pinctrl_apply_state_by_name(dev, "default");
	zassert_equal(ret, 0, "failed to apply default state");
	zassert_equal(pinctrl_soc_check_pins(test_device0_alt_default_pins,
					     ARRAY_SIZE(test_device0_alt_default_pins)),
		      true, "invalid default config");
}

ZTEST_SUITE(pinctrl_api, NULL, NULL, pinctrl_api_before, NULL, NULL);
